const now = Date.now();
const oneHour = 60 * 60 * 1000;
const rows = $input.all().map(i => i.json);

const ready = rows.filter(r => {
  if (r.status !== 'scheduled') return false;
  if (!r.showing_time) return false;
  const showingMs = new Date(r.showing_time).getTime();
  // Window: showing is between now and 1h from now (send when T-60min to T)
  return showingMs >= now && showingMs <= now + oneHour;
});

if (ready.length === 0) return [{ json: { hasReady: false } }];
return ready.map(r => ({ json: { ...r, hasReady: true } }));

function calcWindow(showingTimeISO, availableBeforeMinutes) {
  const dt = new Date(showingTimeISO);
  const pad = n => String(n).padStart(2, '0');

  const effectiveStart = new Date(dt.getTime() - availableBeforeMinutes * 60 * 1000);
  const startUtc = new Date(effectiveStart);
  startUtc.setUTCMinutes(0, 0, 0);

  const showingFloor = new Date(dt);
  showingFloor.setUTCMinutes(0, 0, 0);
  const endUtc = new Date(showingFloor.getTime() + 3600 * 1000);

  const fmt = d => `${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:00`;
  return { startDate: fmt(startUtc), endDate: fmt(endUtc), tzOffset: '0' };
}

const row = $('Find Ready Showings').first().json;
const settings = {};
$('Read Settings (Cron)').all().forEach(i => {
  if (i.json.key && i.json.value) settings[i.json.key] = i.json.value;
});

const appKey    = settings.populife_app_key ?? '';
const appSecret = settings.populife_app_secret ?? '';
if (!appKey || !appSecret) throw new Error('Populife credentials missing from Settings sheet');

const availableBeforeMinutes = parseInt(settings.available_before_minutes || '0');
const { startDate, endDate, tzOffset } = calcWindow(row.showing_time, availableBeforeMinutes);

const populifeLockId = row.populife_lock_id ?? row.populifeLockId ?? '';
if (!populifeLockId) throw new Error('populife_lock_id missing on row ' + row.booking_uid);

// Pass SMS-related settings through for downstream Build SMS
const smsTemplate = settings.access_code_sms_template ?? 'Your access code for {{address}} is: {{code}}';
const fromNumber  = settings.from_number ?? '';

return [{ json: {
  ...row,
  appKey, appSecret,
  startDate, endDate, tzOffset,
  populifeLockId,
  smsTemplate, fromNumber,
} }];

function fmtShowingSlot(showingTimeISO) {
  const start = new Date(showingTimeISO);
  const end   = new Date(start.getTime() + 15 * 60 * 1000);
  const timeFmt = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York', hour: 'numeric', minute: '2-digit', hour12: true
  });
  const dateFmt = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York', month: 'short', day: 'numeric', year: 'numeric'
  });
  return 'Valid from ' + timeFmt.format(start) + ' through ' + timeFmt.format(end) + ', ' + dateFmt.format(start);
}

function fmtTime(iso) {
  try {
    return new Intl.DateTimeFormat('en-US', {
      timeZone: 'America/New_York',
      weekday: 'short', month: 'short', day: 'numeric',
      hour: 'numeric', minute: '2-digit', hour12: true
    }).format(new Date(iso));
  } catch(e) { return iso; }
}

const row    = $('Calc Code Window (Cron)').first().json;
const code   = $('Populife - Generate Code (Cron)').first().json.data?.keyboardPwd ?? '';
const codeId = String($('Populife - Generate Code (Cron)').first().json.data?.keyboardPwdId ?? '');

const validWindow = fmtShowingSlot(row.showing_time);

const message = row.smsTemplate
  .replace('{{first_name}}',   (row.person_name ?? '').split(' ')[0] ?? '')
  .replace('{{name}}',         row.person_name ?? '')
  .replace('{{address}}',      row.property_address ?? row.property_key ?? '')
  .replace('{{date}}',         fmtTime(row.showing_time))
  .replace('{{code}}',         code)
  .replace('{{valid_window}}', validWindow)
  .replace('{{start}}',        row.startDate ?? '')
  .replace('{{end}}',          row.endDate ?? '');

return [{ json: {
  ...row,
  code, codeId, message,
  from_number: row.fromNumber,
  phone: row.person_phone,
  sent_at: new Date().toISOString(),
} }];

// ACCESS_REJECTION_MARKER — last line of defence before a door code goes out.
// Layer 1 (cancelling the booking) normally stops this long before here; this
// only fires when that did not run.

// Deliberately .first() on Find Ready Showings, NOT $json: the whole downstream
// chain (Calc Code Window, Build SMS, Update Showings Row) reads item 0 by named
// reference regardless of which batch iteration is running, so gating on $json
// would evaluate one showing while the pipeline acts on another. See the script
// header, point (a). Fix both together or neither.
const row = $('Find Ready Showings').first().json;
const resp = $json || {};

// This gate is spliced AFTER Read Settings (Cron) precisely so the shared kill
// switch is readable here. Inserting it before that node — the obvious spot —
// would have left layer 2 with no off switch at all.
const settings = {};
$('Read Settings (Cron)').all().forEach(i => { if (i.json.key) settings[i.json.key] = i.json.value; });

const norm = (s) => String(s ?? "").trim().toLowerCase();
const TRASH_TAGS = ["permanent trash", "no response trash", "denied credit"];
const TRASH_STAGES = ["trash", "permanent trash", "cold rental lead 1 month hold"];

const pass = (reason) => {
  console.log("[access-rejection] " + row.booking_uid + " PASS " + reason);
  return [{ json: Object.assign({}, row, { access_blocked: false, block_reason: reason }) }];
};
const block = (reason) => {
  console.log("[access-rejection] " + row.booking_uid + " BLOCK " + reason
    + " person=" + row.person_id + " showing=" + row.showing_time);
  return [{ json: Object.assign({}, row, { access_blocked: true, block_reason: reason }) }];
};

// A backstop that fails closed would strand a verified tenant at the door on a
// FUB outage — the exact harm the 2026-07-28 "stay stage-ungated" decision was
// protecting against. So this one fails OPEN: it only ever blocks on a positive,
// verified rejection signal. Layer 1 is the mechanism that fails closed.
if (resp.error) return pass("fub_error");

// Shared with layer 1, so one switch turns the whole rejection feature off.
// Defaults OFF: applying this patch changes nothing until it is flipped.
if (String(settings.rejection_cancel_enabled ?? 'false').trim().toLowerCase() !== 'true') {
  return pass("disabled");
}

const person = (resp.people && resp.people[0]) ? resp.people[0] : resp;
if (!person || !person.id) return pass("person_not_found");
if (String(person.id) !== String(row.person_id)) return pass("person_id_mismatch:" + person.id);

const stage = norm(person.stage);
const tags = (person.tags || []).map(norm);

// Same two arrays as Check Rejection Guards and Check Nudge Guards, and
// deliberately NOT allowed_stages — outside the allow-list means "not a tenant
// inquiry lead", not "rejected", and a booked showing is reason enough to be
// served (that is the standing 2026-07-28 decision, narrowed only for rejection).
const hitTags = tags.filter(t => TRASH_TAGS.indexOf(t) !== -1);
if (hitTags.length) return block("trash_tag:" + hitTags.join("/"));
if (TRASH_STAGES.indexOf(stage) !== -1) return block("trash_stage:" + stage);

return pass("not_rejected:" + (stage || "(no stage)"));

